CREATE TABLE IF NOT EXISTS task_completion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id VARCHAR(100) NOT NULL UNIQUE,
    completed BOOLEAN NOT NULL DEFAULT FALSE,
    completed_at TIMESTAMP
);
CREATE TABLE IF NOT EXISTS study_session (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,session_date DATE NOT NULL,track VARCHAR(50) NOT NULL,minutes INT NOT NULL,notes VARCHAR(2000));
CREATE TABLE IF NOT EXISTS custom_skill (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_goal (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,skill_name VARCHAR(50) NOT NULL,target_outcome VARCHAR(500) NOT NULL,deadline DATE,weekly_minutes INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_journal (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,journal_date DATE NOT NULL,skill_name VARCHAR(50) NOT NULL,learned VARCHAR(2000),built VARCHAR(2000),difficult VARCHAR(2000),revisit VARCHAR(2000),resources VARCHAR(3000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_review (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,skill_name VARCHAR(50) NOT NULL,topic VARCHAR(500) NOT NULL,source_type VARCHAR(30) NOT NULL DEFAULT 'JOURNAL',source_id BIGINT,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DUE',notes VARCHAR(2000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_project (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(150) NOT NULL,skill_name VARCHAR(50) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PLANNED',outcome VARCHAR(500),repo_url VARCHAR(1000),started_date DATE,target_date DATE,notes VARCHAR(3000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS weekly_review (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,week_start DATE NOT NULL UNIQUE,wins VARCHAR(3000),gaps VARCHAR(3000),next_week VARCHAR(3000),rating INT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS portfolio_evidence (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,skill_name VARCHAR(50) NOT NULL,title VARCHAR(200) NOT NULL,evidence_type VARCHAR(50) NOT NULL,description VARCHAR(2000),url VARCHAR(1000),project_id BIGINT,verified BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS application (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company VARCHAR(150) NOT NULL,role VARCHAR(200) NOT NULL,status VARCHAR(50) NOT NULL DEFAULT 'PLANNED',applied_date DATE,notes VARCHAR(2000));
CREATE TABLE IF NOT EXISTS recognition_activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,activity_date DATE NOT NULL,activity_type VARCHAR(50) NOT NULL,title VARCHAR(250) NOT NULL,url VARCHAR(1000),notes VARCHAR(2000));
CREATE TABLE IF NOT EXISTS dsa_problem (id VARCHAR(100) PRIMARY KEY,title VARCHAR(250) NOT NULL,url VARCHAR(1000) NOT NULL,difficulty VARCHAR(20) NOT NULL,pattern VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS dsa_progress (problem_id VARCHAR(100) PRIMARY KEY,status VARCHAR(30) NOT NULL DEFAULT 'NOT_STARTED',attempts INT NOT NULL DEFAULT 0,time_minutes INT NOT NULL DEFAULT 0,notes VARCHAR(2000),solved_at TIMESTAMP,CONSTRAINT fk_dsa_problem FOREIGN KEY (problem_id) REFERENCES dsa_problem(id));
